"use client";
// @zeus-internal
import { AnimatePresence, LayoutGroup, type MotionValue, motion, useMotionValueEvent, useReducedMotion, useScroll, useTransform, } from "motion/react";
import { type CSSProperties, useEffect, useId, useRef, useState } from "react";
import { ArtemisButton } from "../../../foundations/button";
import { ARTEMIS_EASE_OUT_CSS, ARTEMIS_SPRING_PANEL } from "../../../lib/ease";
import { STEPS } from "./01-pinned-story/data";
import { TourScene } from "./01-pinned-story/stages";
import { StepTabs } from "./01-pinned-story/step-tabs";
const STEP_COUNT = STEPS.length;
const INSTANT = { duration: 0 } as const;
const TAB_ITEMS = STEPS.map((step, i) => ({ value: String(i), label: step.tab }));
function stepFromProgress(progress: number): number {
    return Math.min(STEP_COUNT - 1, Math.max(0, Math.floor(progress * STEP_COUNT)));
}
function StepProgress({ progress, index }: {
    progress: MotionValue<number>;
    index: number;
}) {
    const scaleX = useTransform(progress, [index / STEP_COUNT, (index + 1) / STEP_COUNT], [0, 1]);
    return (<span className="art:mt-4 art:ml-10 art:block art:h-px art:overflow-hidden art:rounded-full art:bg-border">
      <motion.span className="art:block art:h-full art:origin-left art:bg-foreground" style={{ scaleX }}/>
    </span>);
}
export default function ProductTourPinnedStory() {
    const headingId = useId();
    const groupId = useId();
    const reduce = useReducedMotion();
    const trackRef = useRef<HTMLDivElement>(null);
    const desktopRef = useRef(false);
    const [active, setActive] = useState(0);
    const { scrollYProgress } = useScroll({ target: trackRef, offset: ["start start", "end end"] });
    useEffect(() => {
        const host = trackRef.current?.closest(".artemis");
        if (!host) return;
        const sync = () => {
            desktopRef.current = host.clientWidth >= 1024;
            if (desktopRef.current) setActive(stepFromProgress(scrollYProgress.get()));
        };
        sync();
        const observer = new ResizeObserver(sync);
        observer.observe(host);
        return () => observer.disconnect();
    }, [scrollYProgress]);
    useMotionValueEvent(scrollYProgress, "change", (progress) => {
        if (desktopRef.current)
            setActive(stepFromProgress(progress));
    });
    const goToStep = (index: number) => {
        const track = trackRef.current;
        if (!track)
            return;
        const top = track.getBoundingClientRect().top + window.scrollY;
        const range = track.offsetHeight - window.innerHeight;
        window.scrollTo({ top: top + ((index + 0.2) / STEP_COUNT) * range, behavior: reduce ? "auto" : "smooth" });
    };
    const step = STEPS[active];
    const swap = reduce ? INSTANT : ARTEMIS_SPRING_PANEL;
    return (<section className="art:w-full art:bg-background art:px-4 art:py-16 art:font-sans art:text-foreground art:@min-[640px]/artemis:px-8 art:@min-[640px]/artemis:py-20 art:@min-[1024px]/artemis:py-0" aria-labelledby={headingId}>
      <div ref={trackRef} style={{ "--product-tour-track": "320vh" } as CSSProperties} className="art:mx-auto art:w-full art:max-w-6xl art:@min-[1024px]/artemis:h-(--product-tour-track)">
        <div className="art:@min-[1024px]/artemis:sticky art:@min-[1024px]/artemis:top-0 art:@min-[1024px]/artemis:flex art:@min-[1024px]/artemis:h-screen art:@min-[1024px]/artemis:items-center">
          <div className="art:grid art:w-full art:min-w-0 art:grid-cols-1 art:items-center art:gap-10 art:@min-[1024px]/artemis:grid-cols-[minmax(0,0.8fr)_minmax(0,1.2fr)] art:@min-[1024px]/artemis:gap-14">
            <div className="art:min-w-0">
              <p className="art:font-mono art:text-muted-foreground art:text-xs art:uppercase art:tracking-widest">Product tour</p>
              <h2 id={headingId} className="art:mt-4 art:text-balance art:font-medium art:text-4xl art:tracking-tight">
                From scattered requests to a shipped release.
              </h2>
              <p className="art:mt-4 art:max-w-md art:text-pretty art:text-muted-foreground art:leading-7">
                Follow one week of work through the board, from the first request to the notes your customers read.
              </p>
              <ol className="art:mt-10 art:hidden art:@min-[1024px]/artemis:block">
                {STEPS.map((item, i) => {
            const current = i === active;
            return (<li key={item.key} className="art:rounded-2xl art:has-[:focus-visible]:ring-2 art:has-[:focus-visible]:ring-foreground">
                      <ArtemisButton variant="link" size="none" className="art:h-auto art:p-0 art:font-normal art:text-inherit art:hover:bg-transparent art:hover:text-inherit art:block art:w-full art:py-4 art:text-left art:focus-visible:ring-0 art:focus-visible:ring-offset-0" aria-current={current ? "step" : undefined} onClick={() => goToStep(i)}>
                        <span className="art:flex art:items-baseline art:gap-4">
                          <span className="art:w-6 art:shrink-0 art:font-mono art:text-muted-foreground art:text-xs art:tabular-nums">
                            {String(i + 1).padStart(2, "0")}
                          </span>
                          <span className={`art:font-medium art:text-xl art:transition-colors art:duration-300 ${current ? "art:text-foreground" : "art:text-muted-foreground"}`}>
                            {item.title}
                          </span>
                        </span>
                        <span style={{ transitionTimingFunction: ARTEMIS_EASE_OUT_CSS }} className={`art:grid art:pl-10 art:transition-[grid-template-rows,opacity] art:duration-300 art:motion-reduce:transition-none ${current ? "art:grid-rows-[1fr] art:opacity-100" : "art:grid-rows-[0fr] art:opacity-0"}`}>
                          <span className="art:min-h-0 art:overflow-hidden">
                            <span className="art:block art:pt-2 art:text-muted-foreground art:text-sm art:leading-6">{item.body}</span>
                          </span>
                        </span>
                        <StepProgress progress={scrollYProgress} index={i}/>
                      </ArtemisButton>
                    </li>);
        })}
              </ol>
              <div className="art:mt-8 art:@min-[1024px]/artemis:hidden">
                <StepTabs items={TAB_ITEMS} value={String(active)} onValueChange={(value) => setActive(Number(value))}/>
                <AnimatePresence key={reduce ? step.key : "description"} mode="wait" initial={false}>
                  <motion.div key={step.key} className="art:mt-5" aria-live="polite" initial={{ opacity: 0, y: 6 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -4 }} transition={swap}>
                    <h3 className="art:font-medium art:text-xl">{step.title}</h3>
                    <p className="art:mt-2 art:text-muted-foreground art:text-sm art:leading-6">{step.body}</p>
                  </motion.div>
                </AnimatePresence>
              </div>
            </div>
            <div role="img" aria-label={`${step.tab}: ${step.body}`} className="art:relative art:rounded-3xl art:border art:border-border art:bg-background art:p-2">
              <div className="art:flex art:items-center art:justify-between art:px-3 art:py-2">
                <div className="art:flex art:gap-1.5" aria-hidden="true">
                  <span className="art:size-2.5 art:rounded-full art:bg-muted"/>
                  <span className="art:size-2.5 art:rounded-full art:bg-muted"/>
                  <span className="art:size-2.5 art:rounded-full art:bg-muted"/>
                </div>
                <div className="art:relative art:h-5 art:w-40 art:overflow-hidden art:text-right">
                  <AnimatePresence key={reduce ? step.key : "header"} initial={false}>
                    <motion.span key={step.key} className="art:absolute art:inset-0 art:whitespace-nowrap art:font-mono art:text-muted-foreground art:text-xs" initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -10 }} transition={swap}>
                      {step.key} · {"step"} {active + 1}/{STEP_COUNT}
                    </motion.span>
                  </AnimatePresence>
                </div>
              </div>
              <div className="art:relative art:h-[26rem] art:overflow-hidden art:rounded-2xl art:border art:border-border art:p-4 art:@min-[640px]/artemis:p-5">
                <LayoutGroup id={groupId}>
                  <TourScene step={active}/>
                </LayoutGroup>
              </div>
            </div>
          </div>
        </div>
      </div>
    </section>);
}

// @zeus-internal
export type TourStep = {
    key: string;
    tab: string;
    title: string;
    body: string;
};
export const STEPS: readonly TourStep[] = [
    {
        key: "collect",
        tab: "Collect",
        title: "Every request lands in one inbox",
        body: "Feedback from support, sales, and your own team arrives in a single list, already tagged and attributed.",
    },
    {
        key: "sort",
        tab: "Sort",
        title: "Plan the work in three lanes",
        body: "Move requests into Now, Next, and Later so everyone can see what is being built and what is waiting.",
