    {
        key: "review",
        tab: "Review",
        title: "Approve with the context in view",
        body: "Open any item to see its checklist, reviewers, and remaining work before it moves forward.",
    },
    {
        key: "ship",
        tab: "Ship",
        title: "Bundle finished work into a release",
        body: "Completed items roll into release notes your customers can read, while later work stays queued.",
    },
];
export type TourItem = {
    id: string;
    initials: string;
    title: string;
    tag: string;
};
export const ITEMS: readonly TourItem[] = [
    { id: "search", initials: "AL", title: "Faster search", tag: "Core" },
    { id: "csv", initials: "MK", title: "Export to CSV", tag: "Data" },
    { id: "dark", initials: "JR", title: "Dark mode for reports", tag: "Design" },
    { id: "slack", initials: "SO", title: "Slack alerts", tag: "Integrations" },
    { id: "bulk", initials: "TN", title: "Bulk edit tasks", tag: "Core" },
    { id: "usage", initials: "EV", title: "Usage dashboard", tag: "Data" },
];
export const LANES: readonly {
    label: string;
    items: readonly TourItem[];
}[] = [
    { label: "Now", items: ITEMS.slice(0, 2) },
    { label: "Next", items: ITEMS.slice(2, 4) },
    { label: "Later", items: ITEMS.slice(4, 6) },
];
export const REVIEW_ITEM = ITEMS[0];
export const QUEUE_ITEMS = ITEMS.slice(1);
export const REVIEWERS = ["AL", "MK", "JR"] as const;
export const CHECKLIST = [
    "Index rebuilt for large workspaces",
    "Results ranked by recent activity",
    "Keyboard shortcuts documented",
] as const;
export const SHIPPED_ITEMS = ITEMS.slice(0, 4);
export const UP_NEXT_ITEMS = ITEMS.slice(4);

"use client";
// @zeus-internal
import { Check } from "lucide-react";
import { motion, useReducedMotion } from "motion/react";
import type { ReactNode } from "react";
import { ARTEMIS_EASE_OUT, ARTEMIS_SPRING_LAYOUT, ARTEMIS_SPRING_PANEL } from "../../../../lib/ease";
import { artemisCx } from "../../../../lib/utils";
import { CHECKLIST, ITEMS, LANES, QUEUE_ITEMS, REVIEW_ITEM, REVIEWERS, SHIPPED_ITEMS, type TourItem, UP_NEXT_ITEMS, } from "./data";
const INSTANT = { duration: 0 } as const;
const AVATAR = "art:grid art:size-7 art:shrink-0 art:place-items-center art:rounded-full art:bg-muted art:font-medium art:text-xs";
function SceneLabel({ children }: {
    children: ReactNode;
}) {
    return (<motion.p className="art:mb-3 art:font-mono art:text-muted-foreground art:text-xs art:uppercase art:tracking-widest" initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ duration: 0.3, ease: ARTEMIS_EASE_OUT }}>
      {children}
    </motion.p>);
}
function Card({ item, radius, className, children, }: {
    item: TourItem;
    radius: number;
    className?: string;
    children: ReactNode;
}) {
    const reduce = useReducedMotion();
    return (<motion.div layoutId={item.id} className={artemisCx("art:overflow-hidden art:border art:border-border art:bg-background", className)} style={{ borderRadius: radius }} transition={reduce ? INSTANT : ARTEMIS_SPRING_LAYOUT}>
      <motion.div layout initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ duration: 0.25, delay: 0.08, ease: ARTEMIS_EASE_OUT }}>
        {children}
      </motion.div>
    </motion.div>);
}
function CompactCard({ item }: {
    item: TourItem;
}) {
    return (<Card item={item} radius={12}>
      <p className="art:truncate art:px-3 art:py-2 art:text-muted-foreground art:text-xs">{item.title}</p>
    </Card>);
}
function InboxScene() {
    return (<div>
      <SceneLabel>
        {"Inbox"} · {ITEMS.length} {"new"}
      </SceneLabel>
      <div className="art:flex art:flex-col art:gap-2">
        {ITEMS.map((item) => (<Card key={item.id} item={item} radius={14}>
            <div className="art:flex art:items-center art:gap-3 art:px-3 art:py-2.5">
              <span className={AVATAR}>{item.initials}</span>
              <span className="art:min-w-0 art:flex-1 art:truncate art:text-sm">{item.title}</span>
              <span className="art:text-muted-foreground art:text-xs">{item.tag}</span>
            </div>
          </Card>))}
      </div>
    </div>);
}
function LanesScene() {
    return (<div className="art:grid art:h-full art:grid-cols-3 art:gap-3">
      {LANES.map((lane) => (<div key={lane.label} className="art:min-w-0">
          <SceneLabel>
            {lane.label} · {lane.items.length}
          </SceneLabel>
          <div className="art:flex art:flex-col art:gap-2">
            {lane.items.map((item) => (<Card key={item.id} item={item} radius={16}>
                <div className="art:p-3">
                  <p className="art:text-muted-foreground art:text-xs">{item.tag}</p>
                  <p className="art:mt-1 art:font-medium art:text-sm art:leading-5">{item.title}</p>
                  <div className="art:mt-3 art:flex art:justify-end">
                    <span className={AVATAR}>{item.initials}</span>
                  </div>
                </div>
              </Card>))}
          </div>
        </div>))}
    </div>);
}
function ReviewScene() {
    const reduce = useReducedMotion();
    return (<div className="art:grid art:h-full art:gap-3 art:@min-[640px]/artemis:grid-cols-[minmax(0,1fr)_11rem]">
      <div className="art:min-w-0">
        <SceneLabel>In review</SceneLabel>
        <Card item={REVIEW_ITEM} radius={20}>
          <div className="art:p-5">
            <div className="art:flex art:items-center art:justify-between art:gap-3">
              <p className="art:text-muted-foreground art:text-xs">{REVIEW_ITEM.tag}</p>
              <div className="art:flex art:-space-x-1">
                {REVIEWERS.map((initials) => (<span key={initials} className={`${AVATAR} art:ring-2 art:ring-background`}>
                    {initials}
                  </span>))}
              </div>
            </div>
            <p className="art:mt-2 art:font-medium art:text-xl">{REVIEW_ITEM.title}</p>
            <ul className="art:mt-5 art:space-y-3">
              {CHECKLIST.map((line, i) => (<motion.li key={line} className="art:flex art:items-center art:gap-3 art:text-sm" initial={reduce ? false : { opacity: 0, x: -6 }} animate={{ opacity: 1, x: 0 }} transition={reduce ? INSTANT : { ...ARTEMIS_SPRING_PANEL, delay: 0.25 + i * 0.08 }}>
                  <span className="art:grid art:size-5 art:shrink-0 art:place-items-center art:rounded-full art:bg-muted">
                    <Check className="art:size-3" aria-hidden="true"/>
                  </span>
                  {line}
                </motion.li>))}
            </ul>
            <div className="art:mt-6 art:flex art:items-center art:justify-between art:gap-3 art:border-border art:border-t art:pt-4 art:text-sm">
              <span className="art:text-muted-foreground">2 of 3 approvals</span>
              <span className="art:rounded-full art:bg-primary art:px-3 art:py-1.5 art:font-medium art:text-primary-foreground art:text-xs">
                Ready to ship
              </span>
            </div>
          </div>
        </Card>
      </div>
      <div className="art:hidden art:min-w-0 art:@min-[640px]/artemis:block">
        <SceneLabel>Queue</SceneLabel>
        <div className="art:flex art:flex-col art:gap-1.5">
          {QUEUE_ITEMS.map((item) => (<CompactCard key={item.id} item={item}/>))}
        </div>
      </div>
    </div>);
}
function ShipScene() {
    const reduce = useReducedMotion();
    return (<div>
      <SceneLabel>Release</SceneLabel>
      <motion.div className="art:rounded-2xl art:border art:border-border art:p-5" initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={reduce ? INSTANT : ARTEMIS_SPRING_LAYOUT}>
        <div className="art:flex art:items-center art:justify-between art:gap-3">
          <p className="art:font-medium art:text-xl">Version 2.4</p>
          <span className="art:rounded-full art:border art:border-border art:px-2.5 art:py-1 art:text-xs">Published</span>
        </div>
        <p className="art:mt-1 art:text-muted-foreground art:text-sm">
          {SHIPPED_ITEMS.length} {"improvements"} · {"sent to 1,284 readers"}
        </p>
        <div className="art:mt-5 art:flex art:flex-wrap art:gap-2">
          {SHIPPED_ITEMS.map((item) => (<Card key={item.id} item={item} radius={999} className="art:border-foreground/20">
              <p className="art:flex art:items-center art:gap-1.5 art:whitespace-nowrap art:px-3 art:py-1.5 art:text-xs">
                <Check className="art:size-3" aria-hidden="true"/>
