        </div>
      </motion.div>
      <p className="art:mt-6 art:mb-2 art:font-mono art:text-muted-foreground art:text-xs art:uppercase art:tracking-widest">Up next</p>
      <div className="art:grid art:grid-cols-2 art:gap-2">
        {UP_NEXT_ITEMS.map((item) => (<CompactCard key={item.id} item={item}/>))}
      </div>
    </div>);
}
export function TourScene({ step }: {
    step: number;
}) {
    if (step === 1)
        return <LanesScene />;
    if (step === 2)
        return <ReviewScene />;
    if (step === 3)
        return <ShipScene />;
    return <InboxScene />;
}

"use client";
// @zeus-internal
import { ArtemisSegmentedTabs } from "../../../../foundations/segmented-tabs";
export function StepTabs({ items, value, onValueChange }: { items: readonly { value: string; label: string }[]; value: string; onValueChange: (value: string) => void }) {
  return <ArtemisSegmentedTabs items={items} value={value} onValueChange={onValueChange} ariaLabel="Tour steps" listClassName="art:inline-flex art:w-full art:items-center art:gap-1 art:rounded-full art:bg-muted art:p-1 art:*:flex-1" buttonClassName="art:w-full art:rounded-full art:px-2"/>;
}
